@override
def format_auto_rater_prompt(
    self,
    actual_invocation: Invocation,
    _: Optional[Invocation],
) -> str:
  """Returns the autorater prompt."""
  self.create_effective_rubrics_list(actual_invocation.rubrics)
  user_input = get_text_from_content(actual_invocation.user_content)

  include_intermediate = (
      self._criterion.include_intermediate_responses_in_final
  )
  final_response = (
      get_text_from_content(
          actual_invocation,
          include_intermediate_responses_in_final=include_intermediate,
      )
      or ""
  )

  rubrics_text = "\n".join([
      f"*  [id: {r.rubric_id}] {r.rubric_content.text_property}"
      for r in self.get_effective_rubrics_list()
  ])

  developer_instructions = ""
  tool_declarations = "Agent has no tools."
  response_steps = get_tool_calls_and_responses_as_json_str(
      actual_invocation.intermediate_data
  )

  app_details = actual_invocation.app_details
  if app_details:
    if (
        isinstance(actual_invocation.intermediate_data, InvocationEvents)
        and actual_invocation.intermediate_data.invocation_events
    ):
      developer_instructions = app_details.get_developer_instructions(
          agent_name=actual_invocation.intermediate_data.invocation_events[
              0
          ].author
      )
    tool_declarations = get_tool_declarations_as_json_str(app_details)

  auto_rater_prompt = self._auto_rater_prompt_template.format(
      developer_instructions=developer_instructions,
      tool_declarations=tool_declarations,
      user_input=user_input,
      response_steps=response_steps,
      final_response=final_response,
      rubrics=rubrics_text,
  )

  return auto_rater_prompt

def load_json(file_path: str) -> Union[Dict[str, Any], List[Any]]:
  with open(file_path, "r") as f:
    return cast(Union[Dict[str, Any], List[Any]], json.load(f))

def _get_eval_set_blob_name(self, app_name: str, eval_set_id: str) -> str:
  eval_sets_dir = self._get_eval_sets_dir(app_name)
  return f"{eval_sets_dir}/{eval_set_id}{_EVAL_SET_FILE_EXTENSION}"

def _normalize_text(text: object) -> str:
  """Returns a normalized version of the passed in text."""
  if not isinstance(text, str):
    return ""
  return text.lower().strip()

@staticmethod
async def _get_agent_for_eval(
    module_name: str, agent_name: Optional[str] = None
) -> BaseAgent:
  module_path = f"{module_name}"
  agent_module = importlib.import_module(module_path)

  # One of the two things should be satisfied, either the module should have
  # an "agent" as a member in it or the module name itself should end with
  # ".agent".
  if not (hasattr(agent_module, "agent") or module_name.endswith(".agent")):
    raise ValueError(
        f"Module {module_name} does not have a member named `agent` or the"
        " name should endwith `.agent`."
    )

  agent_module_with_agent = (
      agent_module.agent if hasattr(agent_module, "agent") else agent_module
  )
  if hasattr(agent_module_with_agent, "root_agent"):
    root_agent = agent_module_with_agent.root_agent
  elif hasattr(agent_module_with_agent, "get_agent_async"):
    root_agent, _ = await agent_module_with_agent.get_agent_async()
  else:
    raise ValueError(
        f"Module {module_name} does not have a root_agent or"
        " get_agent_async method."
    )

  agent_for_eval = root_agent
  if agent_name:
    agent_for_eval = root_agent.find_agent(agent_name)
    assert agent_for_eval, f"Sub-Agent `{agent_name}` not found."

  return agent_for_eval

def parse_sample_rate(mime_type: str | None, default: int) -> int:
  """Extracts the sample rate from a mime type like 'audio/pcm;rate=24000'."""
  if not mime_type:
    return default
  match = _RATE_RE.search(mime_type)
  return int(match.group(1)) if match else default

@experimental
class MetricEvaluatorRegistry:
  """A registry for metric Evaluators."""

  _registry: dict[str, tuple[type[Evaluator], MetricInfo]] = {}

  def get_evaluator(self, eval_metric: EvalMetric) -> Evaluator:
    """Returns an Evaluator for the given metric.

    A new instance of the Evaluator is returned.

    Args:
      eval_metric: The metric for which we need the Evaluator.

    Raises:
      NotFoundError: If there is no evaluator for the metric.
    """
    if eval_metric.metric_name not in self._registry:
      raise NotFoundError(f"{eval_metric.metric_name} not found in registry.")

    evaluator_type = self._registry[eval_metric.metric_name][0]
    if issubclass(evaluator_type, _CustomMetricEvaluator):
      return evaluator_type(
          eval_metric=eval_metric,
          custom_function_path=eval_metric.custom_function_path,
      )
    return evaluator_type(eval_metric=eval_metric)

  def register_evaluator(
      self,
      metric_info: MetricInfo,
      evaluator: type[Evaluator],
  ) -> None:
    """Registers an evaluator given the metric info.

    If a mapping already exist, then it is updated.
    """
    metric_name = metric_info.metric_name
    if metric_name in self._registry:
      logger.info(
          "Updating Evaluator class for %s from %s to %s",
          metric_name,
          self._registry[metric_name],
          evaluator,
      )

    self._registry[str(metric_name)] = (evaluator, metric_info)

  def get_registered_metrics(
      self,
  ) -> list[MetricInfo]:
    """Returns a list of MetricInfo about the metrics registered so far."""
    return [
        evaluator_and_metric_info[1].model_copy(deep=True)
        for _, evaluator_and_metric_info in self._registry.items()
    ]

class EvalMetric(EvalBaseModel):
  """A metric used to evaluate a particular aspect of an eval case."""

  metric_name: str = Field(
      description="The name of the metric.",
  )

  threshold: Optional[float] = Field(
      default=None,
      description=(
          "This field will be deprecated soon. Please use `criterion` instead."
          " A threshold value. Each metric decides how to interpret this"
          " threshold."
      ),
  )

  criterion: Optional[BaseCriterion] = Field(
      default=None, description="""Evaluation criterion used by the metric."""
  )

  custom_function_path: Optional[str] = Field(
      default=None,
      description="""Path to custom function, if this is a custom metric.""",
  )

@override
def convert_auto_rater_response_to_score(
    self,
    auto_rater_response: LlmResponse,
) -> AutoRaterScore:
  """Returns an AutoRaterScore generated from AutoRater's response."""
  response_text = get_text_from_content(auto_rater_response.content)
  if not response_text:
    logger.warning(
        "Auto-rater returned an empty response; no rubric verdicts could be"
        " parsed and this sample will not be scored."
    )
    rubric_responses = []
  else:
    rubric_responses = self._auto_rater_response_parser.parse(response_text)
    if not rubric_responses:
      logger.warning(
          "Auto-rater response did not match the expected"
          " Property/Rationale/Verdict format; no rubric verdicts were"
          " parsed. Raw auto-rater response: %s",
          response_text,
      )
  rubric_scores = []

  normalized_rubric_to_rubric_map = {}
  for r in self.get_effective_rubrics_list():
    normalized_rubric_to_rubric_map[
        _normalize_text(r.rubric_content.text_property)
    ] = r

  for rubric_response in rubric_responses:
    normalized_rubric_text = _normalize_text(rubric_response.property_text)
    rubric = normalized_rubric_to_rubric_map.get(normalized_rubric_text, None)
    if rubric:
      rubric_scores.append(
          RubricScore(
              rubric_id=rubric.rubric_id,
              rationale=rubric_response.rationale,
              score=rubric_response.score,
          )
      )
    else:
      logger.warning(
          f"Rubric {rubric_response.property_text} not found in the rubrics"
          " provided to the metric."
      )

  aggregated_score = get_average_rubric_score(rubric_scores)
  return AutoRaterScore(score=aggregated_score, rubric_scores=rubric_scores)

