def get_llm_backed_user_simulator_prompt(
    conversation_plan: str,
    conversation_history: str,
    stop_signal: str,
    custom_instructions: Optional[str] = None,
    user_persona: Optional[UserPersona] = None,
):
  """Formats the prompt for the llm-backed user simulator"""
  from jinja2 import DictLoader
  from jinja2 import pass_context
  from jinja2 import Template
  from jinja2.sandbox import SandboxedEnvironment

  templates = {
      "user_instructions": _get_user_simulator_instructions_template(
          custom_instructions=custom_instructions,
          user_persona=user_persona,
      ),
  }
  template_env = SandboxedEnvironment(loader=DictLoader(templates))

  @pass_context
  def _render_string_filter(context, template_string):
    if not template_string:
      return ""
    return Template(template_string).render(context)

  template_env.filters["render_string_filter"] = _render_string_filter

  template_parameters = {
      "stop_signal": stop_signal,
      "conversation_plan": conversation_plan,
      "conversation_history": conversation_history,
  }
  if user_persona is not None:
    template_parameters["persona"] = user_persona

  return template_env.get_template("user_instructions").render(
      template_parameters
  )

@override
def aggregate_invocation_results(
    self, per_invocation_results: list[PerInvocationResult]
) -> EvaluationResult:
  """Computes the fraction of invocation results that are valid."""
  num_valid = 0
  num_evaluated = 0
  for result in per_invocation_results:
    if result.score is None or result.eval_status == EvalStatus.NOT_EVALUATED:
      continue
    num_evaluated += 1
    num_valid += result.score
  overall_score = num_valid / num_evaluated
  return EvaluationResult(
      overall_score=overall_score,
      overall_eval_status=get_eval_status(
          overall_score, self._criterion.threshold
      ),
      per_invocation_results=per_invocation_results,
  )

@override
def format_auto_rater_prompt(
    self,
    actual_invocation: Invocation,
    expected_invocation: Optional[Invocation],
) -> str:
  if expected_invocation is None:
    raise ValueError("expected_invocation is required for this metric.")

  reference = get_text_from_content(expected_invocation.final_response)
  response = get_text_from_content(actual_invocation.final_response)
  user_prompt = get_text_from_content(expected_invocation.user_content)
  return self._auto_rater_prompt_template.format(
      prompt=user_prompt,
      response=response,
      golden_response=reference,
  )

@override
async def evaluate_invocations(
    self,
    actual_invocations: list[Invocation],
    expected_invocations: Optional[list[Invocation]] = None,
    conversation_scenario: Optional[ConversationScenario] = None,
) -> EvaluationResult:
  del expected_invocations  # not used by this metric.
  if conversation_scenario is None:
    raise ValueError("conversation_scenario is needed by this metric.")

  # Evaluate the first invocation contains the given starting prompt.
  results = [
      self._evaluate_first_turn(actual_invocations[0], conversation_scenario)
  ]

  # Evaluate the rest of the invocations.
  for i, invocation in enumerate(actual_invocations):
    # skip the first invocation.
    if i == 0:
      continue

    result = await self._evaluate_intermediate_turn(
        invocation_at_step=invocation,
        invocation_history=actual_invocations[:i],
        conversation_scenario=conversation_scenario,
    )
    results.append(result)

  if not results:
    return EvaluationResult()

  # Evaluate whether the conversation ended correctly.
  stop_signal_evaluation = await self._evaluate_stop_signal_turn(
      invocation_history=actual_invocations,
      conversation_scenario=conversation_scenario,
  )

  # If the conversation did not end correctly, indicate so by marking the
  # last user turn as failed.
  if stop_signal_evaluation.eval_status == EvalStatus.FAILED:
    results[-1] = stop_signal_evaluation

  return self._aggregate_conversation_results(results)

